import Image from "next/image";
import { clsx } from "clsx";
import logo from "../../../public/brand/logo-512.png";

/** The official Monrovia Cinema Plus badge (transparent PNG generated by scripts/make-logo-assets.mjs). */
export function Logo({
  height = 52,
  className,
  priority = false,
  decorative = false,
}: {
  height?: number;
  className?: string;
  priority?: boolean;
  /** Set when the name is also shown as text next to it, so screen readers don't hear it twice. */
  decorative?: boolean;
}) {
  const width = Math.round((height * logo.width) / logo.height);
  return (
    <Image
      src={logo}
      alt={decorative ? "" : "Monrovia Cinema Plus"}
      width={width}
      height={height}
      priority={priority}
      sizes={`${width}px`}
      className={clsx("shrink-0 select-none [filter:drop-shadow(0_0_6px_rgba(226,189,103,0.18))]", className)}
      draggable={false}
    />
  );
}

/** Badge plus the name in type — the badge lettering is too small to read at header sizes. */
export function Wordmark({ className, compact = false, priority = false }: { className?: string; compact?: boolean; priority?: boolean }) {
  return (
    <span className={clsx("inline-flex items-center gap-2.5", className)}>
      <Logo height={compact ? 40 : 52} priority={priority} decorative />
      <span className="flex flex-col leading-none">
        <span className="text-[0.6rem] font-semibold tracking-[0.42em] text-fg-muted">MONROVIA</span>
        <span className="font-display text-[1.25rem] leading-[1.05] text-fg">
          Cinema <span className="gold-text italic">Plus</span>
        </span>
      </span>
      <span className="sr-only">Monrovia Cinema Plus</span>
    </span>
  );
}
